package com.manishrawat.realestate.model; import java.math.BigDecimal;
public class Property { private int id,managerId,bedrooms; private String title,address,city,propertyType,description,status; private BigDecimal price; public int getId(){return id;} public void setId(int v){id=v;} public int getManagerId(){return managerId;} public void setManagerId(int v){managerId=v;} public int getBedrooms(){return bedrooms;} public void setBedrooms(int v){bedrooms=v;} public String getTitle(){return title;} public void setTitle(String v){title=v;} public String getAddress(){return address;} public void setAddress(String v){address=v;} public String getCity(){return city;} public void setCity(String v){city=v;} public String getPropertyType(){return propertyType;} public void setPropertyType(String v){propertyType=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public BigDecimal getPrice(){return price;} public void setPrice(BigDecimal v){price=v;} }
